def validate_settings(value,ids=None):
    if not isinstance(value,dict) or set(value)-{'enabled','slow_seconds','slow_by_app','ui','history_path'}:raise ConfigError('CFG-003 invalid local state')
    enabled=value.get('enabled',{})
    if not isinstance(enabled,dict) or any(not isinstance(v,bool) for v in enabled.values()) or ids and set(enabled)-set(ids):raise ConfigError('CFG-003 invalid enabled state')
    if not isinstance(value.get('slow_by_app',{}),dict) or ids and set(value.get('slow_by_app',{}))-set(ids):raise ConfigError('CFG-003 invalid per-app slow threshold')
    for v in [value.get('slow_seconds',15),*value.get('slow_by_app',{}).values()]:
        if isinstance(v,bool) or not isinstance(v,(int,float)) or not math.isfinite(v) or not 0<v<=3600:raise ConfigError('CFG-003 invalid slow threshold')
    if not isinstance(value.get('ui',{}),dict) or set(value.get('ui',{}))-{'geometry','widths','sort','reverse','placement'}:raise ConfigError('CFG-003 invalid UI preferences')
    ui=value.get('ui',{})
    if 'placement' in ui:
        from .window_placement import valid_placement
        if not valid_placement(ui['placement']):
            raise ConfigError('CFG-003 invalid window placement')
    if not isinstance(ui.get('widths',{}),dict) or any(type(v) is not int or not 20<=v<=8000 for v in ui.get('widths',{}).values()):raise ConfigError('CFG-003 invalid column widths')
    if ui.get('sort') not in (None,'name','family','status','message','checked','successful','duration') or type(ui.get('reverse',False)) is not bool:raise ConfigError('CFG-003 invalid sort preferences')
    if 'geometry' in ui:
        import re
        if not isinstance(ui['geometry'],str) or not re.fullmatch(r'\d{2,4}x\d{2,4}(?:[+-]\d+[+-]\d+)?',ui['geometry']):raise ConfigError('CFG-003 invalid window geometry')
    path=value.get('history_path','output/history.sqlite3')
    if not isinstance(path,str) or not path or Path(path).suffix not in {'.db','.sqlite','.sqlite3'} or Path(path).is_dir():raise ConfigError('CFG-003 invalid history path')
    return value
